import random
import math

def generate_random_planar_graph(n):
    if n < 3:
        return []

    nodes = list(range(n))
    edges = set()

    def add_edge(u, v):
        if u != v and (u, v) not in edges and (v, u) not in edges:
            edges.add((u, v))
            return True
        return False

    def is_planar():
        if len(nodes) <= 4:
            return True

        for i in range(len(nodes)):
            for j in range(i + 1, len(nodes)):
                for k in range(j + 1, len(nodes)):
                    for l in range(k + 1, len(nodes)):
                        if (i, j) in edges and (j, k) in edges and (k, i) in edges:
                            if (i, l) in edges or (l, i) in edges:
                                return False
        return True

    while not is_planar():
        u = random.choice(nodes)
        v = random.choice(nodes)
        add_edge(u, v)

    return list(edges)

def geometric_entropy(G):
    if not G:
        return 0.0

    degree_sum = sum(len(neighbors) for node, neighbors in G.items())
    n = len(G)

    p = [len(neighbors) / degree_sum for node, neighbors in G.items()]
    entropy = -sum(p_i * math.log2(p_i) for p_i in p if p_i > 0)

    return entropy

def communication_rank(G):
    if not G:
        return 0

    rank = 0
    visited = set()

    def dfs(node, parent):
        nonlocal rank
        visited.add(node)
        rank += 1

        for neighbor in G[node]:
            if neighbor != parent and neighbor not in visited:
                dfs(neighbor, node)

    for node in G:
        if node not in visited:
            dfs(node, None)

    return rank

